  const [scopedRestoreOpen, setScopedRestoreOpen] = useState(false); const [scopedRestoreScope, setScopedRestoreScope] = useState<"identities" | "orders">("identities"); const [scopedRestoreFile, setScopedRestoreFile] = useState<File | null>(null); const [scopedRestorePassphrase, setScopedRestorePassphrase] = useState(""); const [scopedRestoreConfirmation, setScopedRestoreConfirmation] = useState(""); const [scopedRestorePreflight, setScopedRestorePreflight] = useState<{ restoreToken: string; expiresAt: string; scope: "identities" | "orders"; orderFileCount: number } | null>(null); const [scopedRestoreBusy, setScopedRestoreBusy] = useState(false);
